import * as atlas from "@atlasauth/pulumi";

const acme = new atlas.IdApp("acme", {
    name: "Acme",
    redirectUris: ["https://acme.example.com/auth/callback"],
    postLogoutRedirectUris: ["https://acme.example.com/"],
    backchannelLogoutUri: "https://acme.example.com/auth/backchannel-logout",
    backchannelLogoutSessionRequired: true,
    allowedScopes: [
        "openid",
        "profile",
        "email",
        "offline_access",
    ],
    logoUrl: "https://acme.example.com/logo.png",
    homepageUrl: "https://acme.example.com",
    branding: JSON.stringify({
        theme: "dark",
