import * as pulumi from "@pulumi/pulumi";
import * as atlas from "@atlasauth/pulumi";

const dashboard = new atlas.OauthClient("dashboard", {
    name: "Internal dashboard",
    redirectUris: ["https://dashboard.example.com/callback"],
});
// Your own app: end the session on RP-initiated logout without the
// "Sign out?" page (first-party clients only).
const web = new atlas.OauthClient("web", {
    name: "Acme web app",
    redirectUris: ["https://app.example.com/callback"],
    firstParty: true,
    skipLogoutConfirmation: true,
});
export const dashboardSecret = dashboard.clientSecret;
