import * as atlas from "@atlasauth/pulumi";

const acme = new atlas.OrganizationPolicy("acme", {
    organizationId: acmeAtlasOrganization.id,
    requireMfa: true,
    ssoRequired: true,
    allowedSignInMethods: [
        "password",
        "oauth_google",
        "saml",
    ],
    ipAllowlists: ["203.0.113.0/24"],
    maxSessionAgeSeconds: 3600,
